          // 需求 → 采购订单（明细已入库）→ 入库单(confirmed) → 批次库存 + 入库流水
          const mockOrderIds = new Set(MOCK_PROCUREMENT_ORDERS.map((o) => o.id));
          const mockDemandIds = new Set(MOCK_PROCUREMENT_DEMANDS.map((d) => d.id));
